useClient

import { useEffect } from "react";
import { useState } from "react";

const backgrounds = ["/naw_web.png", "/maomao.jpeg", "/nawr_web.jpeg", "/ffy_web.jpeg"]
const mobileBackgrounds = ["/naw_mobile.png", "/maomao_mobile.jpeg", "/nawr_web.jpeg", "/ffy_mobile.jpeg"]

function useMediaQuery(query: string) {

        const [matches, setMatches] = useState(() => window.matchMedia(query).matches);

            useEffect(() => {
                const mql = window.matchMedia(query);
                const onChange = (e: MediaQueryListEvent) => setMatches(e.matches);
                mql.addEventListener("change", onChange);
                return () => mql.removeEventListener("change", onChange);
            }, [query]);

    return matches;
}


export default function BackgroundImageComponent({ albumIndex }: { albumIndex: number }) {

    const isMobile = useMediaQuery("(max-width: 768px)");
    const list = isMobile ? mobileBackgrounds : backgrounds;
    const image = list[albumIndex] ?? list[0];

    return  (
        <div
        style={{
            position: "fixed",
            inset: 0,
            zIndex: -1,
            backgroundImage: `url(${image})`,
            backgroundSize: "cover",
            backgroundPosition: "center",
            backgroundRepeat: "no-repeat",
      }}
    />
    );
}